/// The inspector panel (spec §4.3): the tab strip and the scroll view that
/// hosts one pane at a time.
///
/// **Frozen at wiring**, like `EditorViewController` and `TimelineView`: the
/// controls live in the pane files and the shared pieces in
/// `InspectorPane.swift`. What this file owns is the policy —
///
///  - a PICKED clip shows the Clip tab, because that is what the user just
///    asked about — `clipPicked()` for a click (which switches even when the
///    click re-picks the clip that was already selected) and, on top of it, a
///    selection that changed under an unrelated path (paste, ⌘A, the agent),
///    from the Media and Document tabs only — the Assistant and Transcript
///    tabs stay, since the assistant's own calls change the selection
///    mid-turn (spec §11 AI-14), and a click on a clip while the Transcript
///    shows keeps it and scrolls to the clip's first word (TX-20);
///  - a pane is REBUILT only when the model's shape changes
///    (`structureSignature`) and merely refreshed otherwise, so a live canvas
///    drag updates every field without tearing down the control the user is
    /// switches the inspector to the Clip tab". `refresh(isLive:)` cannot
    /// implement that on its own, because a re-click of the ALREADY selected
    /// clip looks exactly like every unrelated refresh — an edit, a playhead
    /// move, an agent op — and switching on those would make the Media and
    /// Document tabs unusable, since almost anything the user did there would
    /// throw them back to Clip. So the pick says so out loud, and the refresh
    /// keeps its own narrower rule for a selection that actually CHANGED
    /// (paste, ⌘A, the agent's `set_selection`).
    ///
    /// Empty selections are ignored: clicking bare lane deselects, and a Clip
    /// tab reading "Select a clip to edit its properties" is not what the user
    /// asked to see.
    func clipPicked() {
        if tab == .transcript { (pane(for: .transcript) as? TranscriptPane)?.reveal(selectedClips); return }
        guard isViewLoaded, !selectedClips.isEmpty else { return }
        select(.clip)
    }

    /// A Clip sub-tab was picked (`ClipSubTabsView`): the one refresh for it.
    func selectClipSubTab(_ tab: ClipSubTab) {
        (pane(for: .clip) as? ClipPane)?.choose(tab)
        refresh(isLive: false)
        scrollToTop()
    }

    /// Hosts the pane's pinned block. The outgoing one is held a generation:
        // Road map creator-jobs TX2a (spec §11 TX-20): the Transcript tab, ⌃⌘T,
        // beside the Assistant's ⌃⌘A; `select_inspector_tab` reaches it too.
        menu.addItem(
            item(
                "Transcript", #selector(EditorViewController.showTranscript(_:)), "t",
                [.command, .control]))
        menu.addItem(
            item(
                "Assistant", #selector(EditorViewController.showAssistant(_:)), "a",
                [.command, .control]))
        menu.addItem(submenuItem(trackHeightMenu()))
        menu.addItem(.separator())
        // Road map 2's phase 8: a group of their own, because both are about
        // the PREVIEW rather than about the editor's own panes. Preview
        // Quality carries the checkmark for the current row, like Timeline
        // Track Height above it; Preview Window carries one for whether the
        // panel is on screen, like Snapping and Safe Areas.
        menu.addItem(submenuItem(previewQualityMenu()))
        menu.addItem(
            item(
                "Preview Window", #selector(EditorViewController.togglePreviewWindow(_:)), "p",
        + "what the person asked for and every preference they stated; the project's name and "
        + "path, and any nest open; every clip, track, marker and media involved, by id, and "
        + "what each is; each edit made, in order, how it turned out, and which were undone; "
        + "what is still open or was promised. Renders do not survive, so describe in words "
        + "what each frame you looked at showed. Write the summary text only, with no tool "
        + "calls."

    /// `text` behind the window's live context (AI-15); `text` alone with no
    /// document. Main only.
    static func message(_ text: String, document: ProjectDocument?) -> String {
        guard let document else { return text }
        return AssistantLiveContext(document: document).text + "\n" + text
    }

    /// "a", "a and b", "a, b and c".
    private static func list(_ items: [String]) -> String {
        guard let last = items.last else { return "" }
        let head = items.dropLast()
        return head.isEmpty ? last : head.joined(separator: ", ") + " and " + last
    }
}
}

enum AssistantToolTable {
    /// The product tools the table names. The dev tools are withheld too, by
    /// `row(for:)`, from `AgentServer.devToolNames`, so a new dev tool needs no
    /// row here.
    static let rows: [AssistantToolRow] = [
        AssistantToolRow(
            tool: "record_screen", rule: .withheld, onlyWith: nil,
            reason: "Recording is a person at the Record button (File ▸ New Recording…)."),
        AssistantToolRow(
            tool: "close_project", rule: .withheld, onlyWith: nil,
            reason: "Closing a project closes the window this conversation lives in (AI-5); the "
                + "person closes it with File ▸ Close (⌘W)."),
        AssistantToolRow(
            tool: "transcribe", rule: .withheld, onlyWith: (key: "engine", value: "assemblyai"),
            reason: "Audio leaves the machine only by name, with the price in front of the "
                + "person (spec §11 R6-2). Use File ▸ Generate Captions…, which shows what is "
